import axios from 'axios';

/**
 * @param {{ username: string, password: string, email: string, profileFile?: File | null }} params
 */
const signup = async ({ username, password, email, profileFile }) => {
    try {
        const fd = new FormData();
        fd.append('username', username);
        fd.append('password', password);
        fd.append('email', email);
        if (profileFile) {
            fd.append('profile', profileFile);
        }

        const request = await axios.post('/auth/signup', fd, {
            withCredentials: true,
        });
        return request.data;
    } catch (err) {
        if (err.response) {
            return err.response.data;
        }

        return {
            success: false,
            message: '서버 연결 실패',
        };
    }
};

export default signup;
